// the waves: one main swell of wave_length running with the wind, three more swells around it and sixteen short, choppy
// waves on top, each a whole number of waves across the patch (so patches tile), with a seeded length, direction and phase
const TAU = 2 * Math.PI, L = size, A = wave_height, wd = wind_direction * Math.PI / 180;
const spacing = L / Math.min(400, Math.max(4, Math.round(L / vertex_spacing)));
const kx = [], kz = [], amp = [], om = [], ph = [];
// shares of the height and of the steepness for the main swell, the other swells and the chop: the chop gets the most
// steepness, so it shows on the backs of the swells and sharpens their crests where it meets them
const share = [0.25, 0.15, 0.6], steep = [0.25, 0.1, 0.65], sums = [0, 0, 0];
for (let i = 0; i < 20; i++) {
  const band = i === 0 ? 0 : i < 4 ? 1 : 2, r1 = rand(i, seed, 1), r2 = i === 0 ? 0 : rand(i, seed, 2) * 2 - 1;
  // the chop is 0.27 to 0.4 wave_length long: 8 to 12 m at the default 30 m swell, so the default 1 m grid draws it whole
  const lam = band === 0 ? wave_length : band === 1 ? wave_length * Math.pow(2, r1 - 0.5) : wave_length * (0.27 + 0.13 * r1);
  const a = wd + r2 * (band === 2 ? 1.2 : 0.5);
  let nx = Math.round(L / lam * Math.cos(a)), nz = Math.round(-L / lam * Math.sin(a));
  if (nx === 0 && nz === 0) { if (Math.abs(Math.cos(a)) >= Math.abs(Math.sin(a))) nx = Math.sign(Math.cos(a)); else nz = -Math.sign(Math.sin(a)); }
  const qx = nx * TAU / L, qz = nz * TAU / L, k = Math.hypot(qx, qz), lq = TAU / k;
  // the band's heights are shared out by w; a wave shorter than eight vertex spacings fades out (gone below four), so the
  // grid never shows waves it cannot draw (no moiré): a coarse grid gets a calmer sea, never more of the other waves
  const w = (1 - 0.5 * Math.abs(r2)) * Math.min(1, lq / wave_length);
  sums[band] += w;
  kx.push(qx); kz.push(qz); amp.push(w * smoothstep(4 * spacing, 8 * spacing, lq)); om.push(Math.sqrt(9.81 * k)); ph.push(rand(i, seed, 3) * TAU);
}
// heights add up to at most wave_height (less where waves fade); choppiness pulls the crests together (Gerstner), the
// steepness adds up to at most 0.95, so the surface never folds over
const c = 0.95 * choppiness, hx = [], hz = [];
for (let i = 0; i < 20; i++) {
  const band = i === 0 ? 0 : i < 4 ? 1 : 2;
  amp[i] *= sums[band] > 0 ? A * share[band] / sums[band] : 0;
  const k = Math.hypot(kx[i], kz[i]), d = A > 0 ? c * steep[band] * amp[i] / (A * share[band] * k) : 0;
  hx.push(d * kx[i] / k); hz.push(d * kz[i] / k);
}
f[]@kx = kx; f[]@kz = kz; f[]@amp = amp; f[]@omega = om; f[]@phase = ph; f[]@hx = hx; f[]@hz = hz;

// the vertex stays on the grid: find the rest position x0 whose wave lands here (x = x0 - D(x0)), then its height
const t = @Time, kx = @kx, kz = @kz, amp = @amp, om = @omega, ph = @phase, hx = @hx, hz = @hz, n = kx.length;
const x = @P.x, z = @P.z;
let x0 = x, z0 = z;
for (let it = 0; it < 8; it++) {
  let dx = 0, dz = 0;
  for (let i = 0; i < n; i++) { const s = Math.sin(kx[i] * x0 + kz[i] * z0 - om[i] * t + ph[i]); dx += hx[i] * s; dz += hz[i] * s; }
  x0 = x + dx; z0 = z + dz;
}
let y = 0, chop = 0, gx = 0, gz = 0, jxx = 1, jzz = 1, jxz = 0, sxx = 1, szz = 1, sxz = 0;
for (let i = 0; i < n; i++) {
  const th = kx[i] * x0 + kz[i] * z0 - om[i] * t + ph[i], s = Math.sin(th), co = Math.cos(th);
  y += amp[i] * co; gx -= amp[i] * kx[i] * s; gz -= amp[i] * kz[i] * s;
  jxx -= hx[i] * kx[i] * co; jzz -= hz[i] * kz[i] * co; jxz -= hx[i] * kz[i] * co;
  if (i < 4) { sxx -= hx[i] * kx[i] * co; szz -= hz[i] * kz[i] * co; sxz -= hx[i] * kz[i] * co; } else chop += amp[i] * co;
}
// slope through the squeeze of the grid (chain rule), so the normals are exact and match across tile borders
const det = jxx * jzz - jxz * jxz, sx = (gx * jzz - gz * jxz) / det, sz = (gz * jxx - gx * jxz) / det;
@P.y = y;
@N = normalize([-sx, 1, -sz]);
// foam where the swells squeeze their crests together, broken up by the chop: more where its crests add to the squeeze,
// none where its troughs pull the surface apart
const squeeze = 1 - (sxx * szz - sxz * sxz), extra = (1 - det) - squeeze;
f@foam = smoothstep(0.07, 0.17, squeeze + 1.5 * extra);
// water colour, baked into the material's base colour map below (the foam goes on top there): deep blue-green troughs,
// paler greener crests; the chop's height counts four times, so the small waves show in the colour too
const deep = [0.0, 0.16, 0.2], crest = [0.08, 0.46, 0.38];
@Cd = mix(deep, crest, wave_height > 0 ? fit(y + 3 * chop, -wave_height, wave_height, 0, 1) : 0.5);
